import { Logger } from '@nestjs/common'
import * as nodemailer from 'nodemailer'

/**
 * Gmail API (HTTPS) mail transport.
 *
 * Why this exists: Railway's trial tier silently blackholes all outbound SMTP
 * (packets dropped, no RST), so nodemailer's SMTP transporter can never deliver
 * in that environment. HTTPS egress is never blocked, so we send the very same
 * RFC822 message over the Gmail REST API instead. See ADR 0009.
 *
 * The message body (MIME) is still generated by nodemailer (via a `streamTransport`
 * that builds but does not send), so we reuse its proven RFC2047 header encoding
 * (Thai subjects → encoded-words), multipart alternative assembly, etc. — we only
 * swap the delivery channel from SMTP to an authenticated HTTPS POST.
 */

const GMAIL_TOKEN_URL = 'https://oauth2.googleapis.com/token'
const GMAIL_SEND_URL =
  'https://gmail.googleapis.com/upload/gmail/v1/users/me/messages/send?uploadType=media'
/** Abort each fetch after this long so a hung socket can never stall a caller. */
const DEFAULT_FETCH_TIMEOUT_MS = 10_000
/** Refresh the access token this far ahead of its real expiry to avoid races. */
const TOKEN_EXPIRY_SKEW_MS = 60_000
/** Cap how much of a Google error body we echo into logs. */
const MAX_ERROR_BODY_LEN = 500

export interface GmailApiTransportOptions {
  clientId: string
  clientSecret: string
  refreshToken: string
  /** Override the 10s per-request timeout (mainly for tests). */
  fetchTimeoutMs?: number
  /** Injectable clock (ms epoch) — lets tests exercise token-cache expiry. */
  now?: () => number
  logger?: Pick<Logger, 'log' | 'warn' | 'error'>
}

/** The fields the caller hands us to turn into an RFC822 message. */
export interface GmailApiMessage {
  from: string
  to: string
  subject: string
  html: string
  text: string
  headers?: Record<string, string>
}

/**
 * Error carrying the HTTP status of a failed Gmail API call. The status drives
 * retry classification in `isTransientMailError` (429/5xx transient, 4xx
 * permanent) — the OPPOSITE of SMTP response-code semantics, hence a distinct
 * field (`httpStatus`) rather than reusing nodemailer's `responseCode`.
 */
export class GmailApiHttpError extends Error {
  constructor(
    message: string,
    readonly httpStatus: number,
  ) {
    super(message)
    this.name = 'GmailApiHttpError'
  }
}

export class GmailApiTransport {
  private readonly clientId: string
  private readonly clientSecret: string
  private readonly refreshToken: string
  private readonly fetchTimeoutMs: number
  private readonly now: () => number
  private readonly logger: Pick<Logger, 'log' | 'warn' | 'error'>

  /** In-memory access-token cache (never persisted — a restart just re-refreshes). */
  private accessToken: string | null = null
  private accessTokenExpiresAt = 0
  /** Lazily built so constructing the transport touches no I/O (keeps boot cheap). */
  private mimeBuilder?: nodemailer.Transporter

  constructor(opts: GmailApiTransportOptions) {
    this.clientId = opts.clientId
    this.clientSecret = opts.clientSecret
    this.refreshToken = opts.refreshToken
    this.fetchTimeoutMs = opts.fetchTimeoutMs ?? DEFAULT_FETCH_TIMEOUT_MS
    this.now = opts.now ?? (() => Date.now())
    this.logger = opts.logger ?? new Logger(GmailApiTransport.name)
  }

  /**
   * Build the raw RFC822 message with nodemailer WITHOUT sending it. `streamTransport`
   * + `buffer: true` makes `info.message` the full MIME buffer; `newline: 'unix'`
   * keeps line endings deterministic. Reusing nodemailer here is deliberate: it
   * already handles RFC2047 encoded-words for non-ASCII (Thai) subjects and the
   * multipart/alternative (text + html) assembly correctly.
   */
  async buildRawMessage(message: GmailApiMessage): Promise<Buffer> {
    const builder = this.getMimeBuilder()
    const info = await builder.sendMail({
      from: message.from,
      to: message.to,
      subject: message.subject,
      html: message.html,
      text: message.text,
      headers: message.headers,
    })
    // streamTransport + buffer:true → info.message is a Buffer of the whole message.
    return (info as unknown as { message: Buffer }).message
  }

  /**
   * POST the raw MIME to Gmail's media-upload send endpoint. Uses the raw-upload
   * variant (`Content-Type: message/rfc822`) so we hand Gmail the bytes verbatim —
   * no base64url `{raw}` bookkeeping. Throws `GmailApiHttpError` on a non-2xx
   * response and lets network/abort errors propagate (both classified downstream).
   */
  async sendRaw(raw: Buffer): Promise<void> {
    const token = await this.getAccessToken()
    const res = await this.fetchWithTimeout(GMAIL_SEND_URL, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'message/rfc822',
      },
      // A Node Buffer isn't in the DOM `BodyInit` union TS models here (its
      // backing store is ArrayBufferLike, not strictly ArrayBuffer). At runtime
      // fetch accepts the Uint8Array view and sends the bytes verbatim.
      body: new Uint8Array(raw.buffer, raw.byteOffset, raw.byteLength) as unknown as BodyInit,
    })
    if (!res.ok) {
      const body = await this.safeReadBody(res)
      // Body is Gmail's error JSON (e.g. {"error":{"code":403,...}}) — it never
      // echoes our bearer token, so it is safe to log. Status drives retry.
      throw new GmailApiHttpError(`Gmail send failed: HTTP ${res.status} ${body}`, res.status)
    }
  }

  /**
   * Boot-time credential probe: force a token refresh so an operator sees at boot
   * whether the OAuth credentials still work. MUST be called fire-and-forget — it
   * does network I/O and boot must never await it.
   */
  async refreshAccessToken(): Promise<void> {
    await this.getAccessToken(true)
  }

  /**
   * Return a valid access token, refreshing via the refresh-token grant when the
   * cached one is missing or within `TOKEN_EXPIRY_SKEW_MS` of expiry. `force`
   * bypasses the cache (used by the boot probe).
   */
  async getAccessToken(force = false): Promise<string> {
    const now = this.now()
    if (
      !force &&
      this.accessToken &&
      now < this.accessTokenExpiresAt - TOKEN_EXPIRY_SKEW_MS
    ) {
      return this.accessToken
    }

    // The request body carries client_secret + refresh_token — NEVER log it.
    const body = new URLSearchParams({
      client_id: this.clientId,
      client_secret: this.clientSecret,
      refresh_token: this.refreshToken,
      grant_type: 'refresh_token',
    })
    const res = await this.fetchWithTimeout(GMAIL_TOKEN_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body,
    })
    if (!res.ok) {
      const errBody = await this.safeReadBody(res)
      // e.g. HTTP 400 {"error":"invalid_grant"} — permanent; a revoked/expired
      // refresh token needs the setup script re-run, not a retry.
      throw new GmailApiHttpError(
        `Gmail token refresh failed: HTTP ${res.status} ${errBody}`,
        res.status,
      )
    }
    const json = (await res.json()) as { access_token?: string; expires_in?: number }
    if (!json.access_token) {
      throw new GmailApiHttpError('Gmail token refresh returned no access_token', res.status)
    }
    this.accessToken = json.access_token
    // Default to 1h if Google omits expires_in (it never does, but be defensive).
    this.accessTokenExpiresAt = now + (json.expires_in ?? 3600) * 1000
    return this.accessToken
  }

  private getMimeBuilder(): nodemailer.Transporter {
    if (!this.mimeBuilder) {
      this.mimeBuilder = nodemailer.createTransport({
        streamTransport: true,
        buffer: true,
        newline: 'unix',
      })
    }
    return this.mimeBuilder
  }

  private async fetchWithTimeout(url: string, init: RequestInit): Promise<Response> {
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), this.fetchTimeoutMs)
    // Don't let the abort timer keep the process (or a Jest worker) alive on its
    // own — the event loop is always running in the live app, so abort still fires.
    timer.unref?.()
    try {
      const fetchImpl = globalThis.fetch
      return await fetchImpl(url, { ...init, signal: controller.signal })
    } finally {
      clearTimeout(timer)
    }
  }

  /** Read an error body defensively — never let a body-read failure mask the HTTP error. */
  private async safeReadBody(res: Response): Promise<string> {
    try {
      const text = await res.text()
      return text.length > MAX_ERROR_BODY_LEN
        ? `${text.slice(0, MAX_ERROR_BODY_LEN)}…`
        : text
    } catch {
      return '(unreadable body)'
    }
  }
}
